package cli

import (
	"fmt"
	"os"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
)

func runCheckoutSync(feature string, push bool, testCmd string, cont, abort, verbose bool) error {
	featurePath, err := internal.RequireFeaturePath(feature)
	if err != nil {
		return err
	}

	// Resolve repo directory (the git working directory)
	repoDir, err := os.Getwd()
	if err != nil {
		return err
	}

	opts := internal.CheckoutSyncOpts{
		Feature:     feature,
		FeaturePath: featurePath,
		RepoDir:     repoDir,
		Push:        push,
		TestCommand: testCmd,
		Verbose:     verbose,
	}

	if abort {
		if err := internal.AbortCheckoutSync(opts); err != nil {
			return err
		}
		fmt.Println("Checkout sync aborted, original branch restored.")
		return nil
	}

	if cont {
		if err := internal.ContinueCheckoutSync(opts); err != nil {
			return err
		}
		fmt.Println("Checkout sync completed.")
		return nil
	}

	// Fresh sync
	if internal.HasCheckoutTransaction(featurePath) {
		return fmt.Errorf("previous checkout-sync incomplete; use --continue or --abort")
	}

	if err := internal.RunCheckoutSync(opts); err != nil {
		return err
	}
	fmt.Println("Checkout sync complete.")
	return nil
}

package cli

import (
	"fmt"
	"os/exec"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func decideCmd() *cobra.Command {
	var decisionType string
	var details string
	var branch string
	var to string

	cmd := &cobra.Command{
		Use:   "decide <feature> <summary>",
		Short: "Record a decision for sibling worktrees to see",
		Args:  cobra.ExactArgs(2),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			feature := args[0]
			summary := args[1]

			featurePath, err := internal.RequireFeaturePath(feature)
			if err != nil {
				return err
			}

			// Auto-detect branch from current worktree if not specified
			if branch == "" {
				if b, err := currentBranch(); err == nil {
					branch = b
				} else {
					branch = "unknown"
				}
			}

			entry, err := internal.AddDecision(featurePath, branch, to, summary, decisionType, details)
			if err != nil {
				return fmt.Errorf("error recording decision: %w", err)
			}

			fmt.Printf("Decision recorded:\n  %s\n", entry)
			return nil
		},
	}

	cmd.Flags().StringVar(&decisionType, "type", "info", "Decision type (breaking, info, deprecation, review, question)")
	cmd.Flags().StringVar(&details, "details", "", "Longer explanation")
	cmd.Flags().StringVar(&branch, "branch", "", "Source branch (auto-detected if omitted)")
	cmd.Flags().StringVar(&to, "to", "", "Target branch (empty = broadcast to all)")

	return cmd
}

func currentBranch() (string, error) {
	out, err := exec.Command("git", "rev-parse", "--abbrev-ref", "HEAD").Output()
	if err != nil {
		return "", err
	}
	return strings.TrimSpace(string(out)), nil
}

package cli

import (
	"fmt"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func decisionsCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "decisions",
		Short: "View and manage decisions for a feature",
	}

	cmd.AddCommand(decisionsListCmd())
	cmd.AddCommand(decisionsAckCmd())

	return cmd
}

func decisionsListCmd() *cobra.Command {
	var branch string
	var mine bool
	var all bool

	cmd := &cobra.Command{
		Use:   "show [feature]",
		Short: "List decisions for a feature (unread by default, auto-detects feature if omitted)",
		Args:  cobra.MaximumNArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			var feature, featurePath string
			if len(args) > 0 {
				feature = args[0]
				fp, err := internal.RequireFeaturePath(feature)
				if err != nil {
					return err
				}
				featurePath = fp
			} else {
				feature, featurePath = internal.DetectFeatureFromCwd()
				if feature == "" {
					return fmt.Errorf("could not detect feature from current directory; usage: tws decisions show <feature> or run from inside a worktree")
				}
			}

			decisions, err := internal.LoadDecisions(featurePath)
			if err != nil {
				fmt.Printf("No decisions found for feature: %s\n", feature)
				return nil
			}

			if len(decisions.Entries) == 0 {
				fmt.Println("No decisions recorded yet.")
				return nil
			}

			// Auto-detect current branch for --mine and unread filtering
			myBranch := ""
			if b, err := currentBranch(); err == nil {
				myBranch = b
			}

			lastRead := 0
			if !all && myBranch != "" {
				lastRead = internal.LastReadID(featurePath, myBranch)
			}

			count := 0
			for _, entry := range decisions.Entries {
				if branch != "" && entry.Branch != branch {
					continue
				}
				if mine && myBranch != "" && !entry.IsRelevantTo(myBranch) {
					continue
				}
				if !all && myBranch != "" && entry.ID <= lastRead {
					continue
				}
				fmt.Println(entry)
				count++
			}

			if count == 0 {
				if all {
					fmt.Println("No decisions match filters.")
				} else {
					fmt.Println("No unread decisions. Use --all to see everything.")
				}
			}
			return nil
		},
	}

	cmd.Flags().StringVar(&branch, "branch", "", "Filter by source branch")
	cmd.Flags().BoolVar(&mine, "mine", false, "Show only decisions relevant to current branch")
	cmd.Flags().BoolVar(&all, "all", false, "Show all decisions (including already read)")

	return cmd
}

func decisionsAckCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "ack [feature]",
		Short: "Mark all decisions as read for current branch",
		Args:  cobra.MaximumNArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			var featurePath string
			if len(args) > 0 {
				fp, err := internal.RequireFeaturePath(args[0])
				if err != nil {
					return err
				}
				featurePath = fp
			} else {
				_, featurePath = internal.DetectFeatureFromCwd()
				if featurePath == "" {
					return fmt.Errorf("could not detect feature; usage: tws decisions ack <feature>")
				}
			}

			branch, err := currentBranch()
			if err != nil {
				return fmt.Errorf("could not detect current branch")
			}

			if err := internal.AckDecisions(featurePath, branch); err != nil {
				return err
			}

			fmt.Printf("Marked all decisions as read for branch: %s\n", branch)
			return nil
		},
	}
}

