package cli

import (
	"fmt"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func syncCmd() *cobra.Command {
	var verbose bool
	var push bool
	var cont bool
	var abort bool
	var testCmd string

	cmd := &cobra.Command{
		Use:   "sync <feature>",
		Short: "Rebase branches in dependency order",
		Args:  cobra.ExactArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			internal.RequireTool("git")

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}
			if ws.Mode == internal.ModeCheckout {
				return runCheckoutSync(args[0], push, testCmd, cont, abort, verbose)
			}

			feature := args[0]
			featurePath, fpErr := ws.ResolveFeaturePath(feature)
			if fpErr != nil {
				return fpErr
			}

			if abort {
				return handleSyncAbort(feature, featurePath)
			}
			if cont {
				return handleSyncContinue(feature, featurePath, push)
			}
			if internal.HasSyncState(featurePath) {
				state, _ := internal.LoadSyncState(featurePath)
				return fmt.Errorf("previous sync incomplete (failed on: %s); use --continue or --abort", state.FailedBranch)
			}

			result := syncFeature(feature, verbose)
			if !result.Complete {
				return fmt.Errorf("sync incomplete")
			}
			fmt.Println("Sync complete.")
			if push {
				fmt.Println("\nPushing...")
				if err := pushFeature(feature, false); err != nil {
					return err
				}
			}
			return nil
		},
	}

	cmd.Flags().BoolVarP(&verbose, "verbose", "v", false, "Show full git fetch output")
	cmd.Flags().BoolVar(&push, "push", false, "Push all branches after syncing")
	cmd.Flags().BoolVar(&cont, "continue", false, "Resume after conflict resolution")
	cmd.Flags().BoolVar(&abort, "abort", false, "Discard sync state and start fresh")
	cmd.Flags().StringVar(&testCmd, "test", "", "Validation command to run after each rebase (checkout mode)")

	return cmd
}

func handleSyncAbort(feature, featurePath string) error {
	state, err := internal.LoadSyncState(featurePath)
	if err != nil {
		fmt.Println("Nothing to abort — no sync in progress.")
		return nil
	}
	if state.FailedBranch != "" {
		path := internal.WorktreePath(feature, state.FailedBranch)
		if isRebaseInProgress(path) {
			_ = internal.RunSilentDir(path, "git", "rebase", "--abort")
		}
	}
	internal.DeleteSyncState(featurePath)
	fmt.Println("Sync state cleared.")
	return nil
}

func handleSyncContinue(feature, featurePath string, push bool) error {
	state, err := internal.LoadSyncState(featurePath)
	if err != nil {
		return fmt.Errorf("nothing to continue — no sync in progress")
	}
	failedPath := internal.WorktreePath(feature, state.FailedBranch)
	if state.FailedBranch != "" && isRebaseInProgress(failedPath) {
		return fmt.Errorf("rebase still in progress in %s; resolve conflicts, run git add . && git rebase --continue, then retry", state.FailedBranch)
	}

	stack, err := internal.LoadStack(featurePath)
	if err != nil {
		return fmt.Errorf("load stack: %w", err)
	}
	if state.FailedBranch != "" {
		failedEntry := internal.GetBranch(stack, state.FailedBranch)
		if failedEntry.Name == "" {
			return fmt.Errorf("failed branch %q no longer exists in stack", state.FailedBranch)
		}
		if !branchContainsConfiguredParent(feature, stack, failedEntry) {
			return fmt.Errorf("resolved branch %s still does not contain its configured parent %s", failedEntry.Name, failedEntry.Base)
		}
		fmt.Println(formatSyncStatus(state.FailedBranch, "active", "resolved"))
	}

	done := make(map[string]bool)
	for _, name := range state.Completed {
		done[name] = true
	}
	if state.FailedBranch != "" {
		done[state.FailedBranch] = true
	}
	sorted, err := internal.TopoSort(stack)
	if err != nil {
		return err
	}
	fmt.Printf("Resuming sync with %d pending branch(es)\n", len(state.Pending))
	result := syncWithStackFiltered(feature, featurePath, stack, sorted, done)
	if !result.Complete {
		return fmt.Errorf("sync incomplete")
	}
	fmt.Println("Sync complete.")
	if push {
		fmt.Println("\nPushing...")
		if err := pushFeature(feature, false); err != nil {
			return err
		}
	}
	return nil
}

func branchContainsConfiguredParent(feature string, stack internal.Stack, child internal.StackEntry) bool {
	parent := internal.GetBranch(stack, child.Base)
	if parent.Name == "" || !sameStackRepo(parent.Repo, child.Repo) {
		return true
	}
	path := internal.WorktreePath(feature, child.Name)
	return internal.RunSilentDir(path, "git", "merge-base", "--is-ancestor", parent.GitBranch(), child.GitBranch()) == nil
}

func isRebaseInProgress(worktreePath string) bool {
	// Check for .git/rebase-merge or .git/rebase-apply
	gitDir := internal.RunSilent("git", "-C", worktreePath, "rev-parse", "--git-dir")
	if gitDir != nil {
		return false
	}
	// Simpler: check if git status shows rebase
	err := internal.RunSilent("git", "-C", worktreePath, "rebase", "--show-current-patch")
	return err == nil
}

func syncFeature(feature string, verbose bool) syncResult {
	featurePath := internal.FeaturePath(feature)

	stack, err := internal.LoadStack(featurePath)
	if err != nil {
		fetchQuiet("", "", verbose)
		syncFallback(featurePath)
		return syncResult{Complete: true}
	}

	repos := internal.UniqueRepos(stack, featurePath)
	for repo, wtPath := range repos {
		fetchQuiet(repo, wtPath, verbose)
	}

	sorted, err := internal.TopoSort(stack)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return syncResult{}
	}
	return syncWithStack(feature, featurePath, stack, sorted)
}

func fetchQuiet(repo, wtPath string, verbose bool) {
	label := "default repo"
	if repo != "" {
		label = repo
	}

	if verbose {
		fmt.Printf("Fetching %s...\n", label)
		if wtPath != "" {
			_ = internal.RunDir(wtPath, "git", "fetch")
		} else if repo != "" {
			_ = internal.RunDir(repo, "git", "fetch")
		} else {
			_ = internal.Run("git", "fetch")
		}
	} else {
		fmt.Printf("Fetching %s... ", label)
		var err error
		if wtPath != "" {
			err = internal.RunSilentDir(wtPath, "git", "fetch")
		} else if repo != "" {
			err = internal.RunSilentDir(repo, "git", "fetch")
		} else {
			err = internal.RunSilent("git", "fetch")
		}
		if err != nil {
			fmt.Println("failed")
		} else {
			fmt.Println("done")
		}
	}
}

package cli

import (
	"fmt"
	"os"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func templateCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "template",
		Short: "Manage workspace templates",
	}

	cmd.AddCommand(templateSyncCmd())

	return cmd
}

func templateSyncCmd() *cobra.Command {
	var templates []string
	var all bool

	cmd := &cobra.Command{
		Use:   "sync [feature]",
		Short: "Apply template files to existing feature(s)",
		Long:  "Copy template files into a feature's inject/ directory. Skips existing files. Use --all to sync all features.",
		Args:  cobra.MaximumNArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		Run: func(cmd *cobra.Command, args []string) {
			if all {
				features := internal.ListFeatures()
				if len(features) == 0 {
					fmt.Println("No features found.")
					return
				}
				for _, feature := range features {
					syncFeatureTemplate(feature, templates)
				}
				return
			}

			if len(args) == 0 {
				fmt.Println("Usage: tws template sync <feature> [--template <dir>]")
				fmt.Println("       tws template sync --all")
				os.Exit(1)
			}

			syncFeatureTemplate(args[0], templates)
		},
	}

	cmd.Flags().StringArrayVar(&templates, "template", nil, "Template directory (can be specified multiple times)")
	cmd.Flags().BoolVar(&all, "all", false, "Sync all features")

	return cmd
}

func syncFeatureTemplate(feature string, extraTemplates []string) {
	featurePath, err := internal.RequireFeaturePath(feature)
	if err != nil {
		fmt.Printf("%s: %v\n", feature, err)
		return
	}

	injectDir := internal.InjectPath(featurePath)
	if err := os.MkdirAll(injectDir, 0755); err != nil {
		fmt.Printf("%s: error creating inject dir: %v\n", feature, err)
		return
	}

	fmt.Printf("%s:\n", feature)
	applyTemplates(injectDir, extraTemplates)

	// Re-sync inject into worktrees
	target := internal.ResolveInjectInto("")
	count, err := internal.InjectFilesForFeature(featurePath, target)
	if err != nil {
		fmt.Printf("  Warning: worktree inject failed: %v\n", err)
	} else if count > 0 {
		fmt.Printf("  Synced inject to %d worktree(s)\n", count)
	}
}

package internal

import (
	"os"
	"path/filepath"
	"strings"
)

const workspaceMarker = ".tws-workspace"

// DetectWorkspaceRoot checks if cwd is inside an existing workspace.
// Returns the workspace root or empty string.
func DetectWorkspaceRoot(cwd string, cfg Config) string {
	// Tier 1: Walk up looking for .tws-workspace marker
	dir := cwd
	for {
		if _, err := os.Stat(filepath.Join(dir, workspaceMarker)); err == nil {
			return dir
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			break
		}
		dir = parent
	}

	// Tier 2: Check if cwd is inside any configured workspace path
	for _, ws := range cfg.Workspaces {
		absWs, err := filepath.Abs(ws)
		if err != nil {
			continue
		}
		absCwd, err := filepath.Abs(cwd)
		if err != nil {
			continue
		}
		if strings.HasPrefix(absCwd, absWs+string(filepath.Separator)) || absCwd == absWs {
			return absWs
		}
	}

	// Tier 3: Check if cwd is inside ~/tws
	home, _ := os.UserHomeDir()
	globalDefault := filepath.Join(home, "tws")
	absCwd, _ := filepath.Abs(cwd)
	if strings.HasPrefix(absCwd, globalDefault+string(filepath.Separator)) || absCwd == globalDefault {
		return globalDefault
	}

	return ""
}

// resolveTwsRoot contains the resolution logic with injectable dependencies.
// It routes through resolveWorkspaceMetadataRoot to honour workspace mode
// while preserving byte-for-byte external outputs for existing callers.
func resolveTwsRoot(envRoot string, cwd string, repoRoot string, repoErr error, cfg Config) string {
	// 0. TWS_ROOT env var — always wins
	if envRoot != "" {
		return envRoot
	}

	// 1. Already inside a workspace? Return that root.
	if wsRoot := DetectWorkspaceRoot(cwd, cfg); wsRoot != "" {
		return wsRoot
	}

	// 2. Route through workspace resolver (handles mode + config + sibling).
	if root := resolveWorkspaceMetadataRoot(repoRoot, repoErr, cfg); root != "" {
		return root
	}

	// 3. Global fallback (no repo detected).
	home, _ := os.UserHomeDir()
	return filepath.Join(home, "tws")
}

func TwsRoot() string {
	repoRoot, repoErr := MainRepoRoot()
	cfg := LoadConfig()
	cwd, _ := os.Getwd()
	return resolveTwsRoot(os.Getenv("TWS_ROOT"), cwd, repoRoot, repoErr, cfg)
}

func FeaturePath(feature string) string {
	return filepath.Join(TwsRoot(), feature)
}

func WorktreePath(feature, branch string) string {
	return filepath.Join(FeaturePath(feature), "worktrees", branch)
}

// DetectFeatureFromCwd detects the current feature name from the working directory.
// Works when cwd is inside a worktree: <workspace>/<feature>/worktrees/<branch>/
// Returns feature name and feature path, or empty strings if not detected.
func DetectFeatureFromCwd() (string, string) {
	cwd, err := os.Getwd()
	if err != nil {
		return "", ""
	}

	wsRoot := TwsRoot()
	absWs, _ := filepath.Abs(wsRoot)
	absCwd, _ := filepath.Abs(cwd)

	// Check if cwd is inside the workspace
	if !strings.HasPrefix(absCwd, absWs+string(filepath.Separator)) {
		return "", ""
	}

	// Get the relative path from workspace root
	rel, err := filepath.Rel(absWs, absCwd)
	if err != nil {
		return "", ""
	}

	// First component is the feature name
	parts := strings.SplitN(rel, string(filepath.Separator), 2)
	if len(parts) == 0 {
		return "", ""
	}

	feature := parts[0]
	featurePath := filepath.Join(absWs, feature)

	// Verify it's actually a feature dir (has stack.yaml or worktrees/)
	if _, err := os.Stat(filepath.Join(featurePath, "worktrees")); err == nil {
		return feature, featurePath
	}
	if _, err := os.Stat(filepath.Join(featurePath, "stack.yaml")); err == nil {
		return feature, featurePath
	}

	return "", ""
}

// ListFeatures returns the sorted feature names for the resolved workspace.
// External mode preserves the legacy sibling-workspace behavior; checkout mode
// merges new and legacy layouts while excluding internal metadata directories.
func ListFeatures() []string {
	if ws, err := RequireWorkspace(); err == nil {
		features, listErr := ws.ListFeaturesResolved()
		if listErr == nil {
			return features
		}
		return nil
	}
	entries, err := os.ReadDir(TwsRoot())
	if err != nil {
		return nil
	}
	var features []string
	for _, entry := range entries {
		if entry.IsDir() && entry.Name() != ".tws-workspace" {
			features = append(features, entry.Name())
		}
	}
	return features
}

// ListBranches returns the branch names for a feature from stack.yaml,
// or from the worktrees directory if no stack exists.
func ListBranches(feature string) []string {
	featurePath, err := RequireFeaturePath(feature)
	if err != nil {
		return nil
	}
	stack, err := LoadStack(featurePath)
	if err == nil && len(stack.Branches) > 0 {
		var names []string
		for _, e := range stack.Branches {
			names = append(names, e.Name)
		}
		return names
	}

	// Fallback: list worktree directories
	wtDir := filepath.Join(featurePath, "worktrees")
	entries, err := os.ReadDir(wtDir)
	if err != nil {
		return nil
	}
	var names []string
	for _, e := range entries {
		if e.IsDir() {
			names = append(names, e.Name())
		}
	}
	return names
}

package internal

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// ErrWorktreeUnsupported is returned when a caller attempts to use worktree
// paths in checkout mode, which does not support linked worktrees.
var ErrWorktreeUnsupported = errors.New("linked worktrees are not supported in checkout mode")

// ErrAmbiguousFeature is returned when a feature exists in both legacy and
// new layout paths.
type ErrAmbiguousFeature struct {
	Feature    string
	LegacyPath string
	NewPath    string
}

func (e *ErrAmbiguousFeature) Error() string {
	return fmt.Sprintf("ambiguous feature %q: exists at both %s and %s; run 'tws migrate-layout %s' to resolve",
		e.Feature, e.LegacyPath, e.NewPath, e.Feature)
}

// ResolveFeaturePath returns the path to a feature, erroring if ambiguous.
// For checkout mode:
//   - New layout: <repoRoot>/.tws/features/<feature>
//   - Legacy layout: <metadataRoot>/<feature> (the old sibling-dir style)
//
// If both exist, returns ErrAmbiguousFeature.
// For external mode, returns the standard MetadataRoot/<feature> path.
func (w Workspace) ResolveFeaturePath(feature string) (string, error) {
	if err := validateFeatureName(feature); err != nil {
		return "", err
	}

	if w.Mode != ModeCheckout {
		return filepath.Join(w.MetadataRoot, feature), nil
	}

	newPath := filepath.Join(w.MetadataRoot, "features", feature)
	legacyPath := filepath.Join(w.MetadataRoot, feature)

	newExists := dirExists(newPath)
	legacyExists := dirExists(legacyPath) && !isReservedDir(feature)

	if newExists && legacyExists {
		return "", &ErrAmbiguousFeature{Feature: feature, LegacyPath: legacyPath, NewPath: newPath}
	}
	if newExists {
		return newPath, nil
	}
	if legacyExists {
		return legacyPath, nil
	}

	// Neither exists; default to new layout.
	return newPath, nil
}

// ResolveFeaturePathOrLegacy is like ResolveFeaturePath but for read-only
// operations that need to find existing features. Returns ("", nil) if not found.
func (w Workspace) ResolveFeaturePathOrLegacy(feature string) (string, error) {
	if err := validateFeatureName(feature); err != nil {
		return "", err
	}

	if w.Mode != ModeCheckout {
		p := filepath.Join(w.MetadataRoot, feature)
		if dirExists(p) {
			return p, nil
		}
		return "", nil
	}

	newPath := filepath.Join(w.MetadataRoot, "features", feature)
	legacyPath := filepath.Join(w.MetadataRoot, feature)

	newExists := dirExists(newPath)
	legacyExists := dirExists(legacyPath) && !isReservedDir(feature)

	if newExists && legacyExists {
		return "", &ErrAmbiguousFeature{Feature: feature, LegacyPath: legacyPath, NewPath: newPath}
	}
	if newExists {
		return newPath, nil
	}
	if legacyExists {
		return legacyPath, nil
	}
	return "", nil
}

// LegacyFeatureNames returns sorted legacy checkout feature names.
func (w Workspace) LegacyFeatureNames() []string {
	if w.Mode != ModeCheckout {
		return nil
	}
	var names []string
	if entries, err := os.ReadDir(w.MetadataRoot); err == nil {
		for _, entry := range entries {
			if entry.IsDir() && !isReservedDir(entry.Name()) {
				names = append(names, entry.Name())
			}
		}
	}
	sort.Strings(names)
	return names
}

// ListFeaturesResolved returns sorted feature names for the workspace,
// excluding reserved internal directories.
func (w Workspace) ListFeaturesResolved() ([]string, error) {
	seen := make(map[string]bool)

	if w.Mode == ModeCheckout {
		// New layout: .tws/features/*
		featuresDir := filepath.Join(w.MetadataRoot, "features")
		if entries, err := os.ReadDir(featuresDir); err == nil {
			for _, e := range entries {
				if e.IsDir() && !isReservedDir(e.Name()) {
					seen[e.Name()] = true
				}
			}
		}
		// Legacy layout: .tws/<feature> (non-reserved dirs in MetadataRoot)
		if entries, err := os.ReadDir(w.MetadataRoot); err == nil {
			for _, e := range entries {
				if e.IsDir() && !isReservedDir(e.Name()) && !seen[e.Name()] {
					seen[e.Name()] = true
				}
			}
		}
	} else {
		if entries, err := os.ReadDir(w.MetadataRoot); err == nil {
			for _, e := range entries {
				if e.IsDir() && !isReservedDir(e.Name()) {
					seen[e.Name()] = true
				}
			}
		}
	}

	names := make([]string, 0, len(seen))
	for name := range seen {
		names = append(names, name)
	}
	sort.Strings(names)
	return names, nil
}

// reservedDirs are directories in .tws/ that are NOT features.
var reservedDirs = map[string]bool{
	"config.yaml": true,
	"features":    true,
	"state":       true,
	"templates":   true,
	"hooks":       true,
	"skills":      true,
}

func isReservedDir(name string) bool {
	return reservedDirs[name] || strings.HasPrefix(name, ".")
}

// validateFeatureName rejects unsafe feature names (path traversal, symlinks, etc).
func validateFeatureName(name string) error {
	if name == "" {
		return fmt.Errorf("feature name cannot be empty")
	}
	if strings.Contains(name, "/") || strings.Contains(name, "\\") {
		return fmt.Errorf("feature name %q contains path separator", name)
	}
	if strings.Contains(name, "..") {
		return fmt.Errorf("feature name %q contains path traversal", name)
	}
	if name == "." || name == ".." {
		return fmt.Errorf("feature name %q is reserved", name)
	}
	if isReservedDir(name) {
		return fmt.Errorf("feature name %q conflicts with reserved directory", name)
	}
	// Reject names that would be symlinks at the target.
	return nil
}

func dirExists(path string) bool {
	info, err := os.Lstat(path)
	if err != nil {
		return false
	}
	// Reject symlinks.
	if info.Mode()&os.ModeSymlink != 0 {
		return false
	}
	return info.IsDir()
}

// DetectFeatureFromCwdE is a mode-aware version of DetectFeatureFromCwd.
// It handles new layout (.tws/features/<f>), legacy layout (.tws/<f>),
// and repo root detection.
func (w Workspace) DetectFeatureFromCwdE(cwd string) (feature, branch string) {
	if w.Mode == ModeCheckout {
		// New layout: cwd under .tws/features/<feature>/...
		featuresDir := filepath.Join(w.MetadataRoot, "features")
		if rel, err := filepath.Rel(featuresDir, cwd); err == nil && !strings.HasPrefix(rel, "..") {
			parts := strings.SplitN(rel, string(filepath.Separator), 2)
			if len(parts) >= 1 && parts[0] != "." {
				return parts[0], ""
			}
		}
	}

	// Legacy/external: cwd under MetadataRoot/<feature>/...
	if rel, err := filepath.Rel(w.MetadataRoot, cwd); err == nil && !strings.HasPrefix(rel, "..") {
		parts := strings.SplitN(rel, string(filepath.Separator), 2)
		if len(parts) >= 1 && parts[0] != "." && !isReservedDir(parts[0]) {
			feat := parts[0]
			if len(parts) >= 2 {
				// Might be in worktrees/<branch>
				sub := strings.SplitN(parts[1], string(filepath.Separator), 2)
				if sub[0] == "worktrees" && len(sub) >= 2 {
					branchParts := strings.SplitN(sub[1], string(filepath.Separator), 2)
					return feat, branchParts[0]
				}
			}
			return feat, ""
		}
	}

	return "", ""
}

// CheckoutStateDir returns the state directory for the workspace.
// Always .tws/state/ regardless of whether features are in legacy or new layout.
func (w Workspace) CheckoutStateDir() string {
	return filepath.Join(w.MetadataRoot, "state")
}

// RequireFeaturePath is the package-level error-returning feature path resolver.
// It calls RequireWorkspace and then ResolveFeaturePath. Callers must propagate
// errors (ambiguity, invalid workspace_mode) instead of silently falling back.
func RequireFeaturePath(feature string) (string, error) {
	ws, err := RequireWorkspace()
	if err != nil {
		return "", err
	}
	return ws.ResolveFeaturePath(feature)
}

// RequireWorktreePath resolves a worktree path through the workspace layer.
// Returns ErrWorktreeUnsupported in checkout mode.
func RequireWorktreePath(feature, worktree string) (string, error) {
	ws, err := RequireWorkspace()
	if err != nil {
		return "", err
	}
	p := ws.WorktreePath(feature, worktree)
	if p == "" {
		return "", ErrWorktreeUnsupported
	}
	return p, nil
}

package internal

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestResolveFeaturePath_NewLayout(t *testing.T) {
	dir := t.TempDir()
	ws := Workspace{MetadataRoot: dir, Mode: ModeCheckout}

	// Create new layout feature.
	if err := os.MkdirAll(filepath.Join(dir, "features", "myfeature"), 0755); err != nil {
		t.Fatal(err)
	}

	got, err := ws.ResolveFeaturePath("myfeature")
	if err != nil {
		t.Fatal(err)
	}
	if got != filepath.Join(dir, "features", "myfeature") {
		t.Errorf("got %s", got)
	}
}

func TestResolveFeaturePath_LegacyLayout(t *testing.T) {
	dir := t.TempDir()
	ws := Workspace{MetadataRoot: dir, Mode: ModeCheckout}

	// Create legacy feature.
	if err := os.MkdirAll(filepath.Join(dir, "myfeature"), 0755); err != nil {
		t.Fatal(err)
	}

	got, err := ws.ResolveFeaturePath("myfeature")
	if err != nil {
		t.Fatal(err)
	}
	if got != filepath.Join(dir, "myfeature") {
		t.Errorf("got %s", got)
	}
}

func TestResolveFeaturePath_Ambiguous(t *testing.T) {
	dir := t.TempDir()
	ws := Workspace{MetadataRoot: dir, Mode: ModeCheckout}

	// Create both.
	if err := os.MkdirAll(filepath.Join(dir, "features", "myfeature"), 0755); err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(filepath.Join(dir, "myfeature"), 0755); err != nil {
		t.Fatal(err)
	}

	_, err := ws.ResolveFeaturePath("myfeature")
	if err == nil {
		t.Fatal("expected ambiguity error")
	}
	var ambErr *ErrAmbiguousFeature
	if !strings.Contains(err.Error(), "ambiguous") {
		t.Errorf("expected ambiguous error, got: %v", err)
	}
	_ = ambErr
}

func TestResolveFeaturePath_ReservedDirNotLegacy(t *testing.T) {
	dir := t.TempDir()
	ws := Workspace{MetadataRoot: dir, Mode: ModeCheckout}

	// "features" dir exists at root but is reserved -- should not be treated as legacy.
	if err := os.MkdirAll(filepath.Join(dir, "features"), 0755); err != nil {
		t.Fatal(err)
	}

	got, err := ws.ResolveFeaturePath("newfeature")
	if err != nil {
		t.Fatal(err)
	}
	// Should default to new layout.
	if !strings.Contains(got, "features/newfeature") {
		t.Errorf("expected new layout path, got %s", got)
	}
}

func TestResolveFeaturePath_ExternalMode(t *testing.T) {
	dir := t.TempDir()
	ws := Workspace{MetadataRoot: dir, Mode: ModeExternal}

	got, err := ws.ResolveFeaturePath("feat")
	if err != nil {
		t.Fatal(err)
	}
	if got != filepath.Join(dir, "feat") {
		t.Errorf("got %s", got)
	}
}

